ALTER TABLE public.video_walls ADD CONSTRAINT wall_position_valid CHECK(position_seconds>=0 AND position_seconds<'Infinity'::double precision);
CREATE FUNCTION public.validate_wall_geometry() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.video_wall_screens WHERE wall_id=NEW.id AND (row_index>=NEW.rows OR column_index>=NEW.columns)) THEN RAISE EXCEPTION 'Existing screen outside new grid'; END IF; IF TG_OP='UPDATE' AND (NEW.columns,NEW.rows,NEW.width,NEW.height,NEW.gap_x,NEW.gap_y,NEW.orientation) IS DISTINCT FROM (OLD.columns,OLD.rows,OLD.width,OLD.height,OLD.gap_x,OLD.gap_y,OLD.orientation) THEN NEW.state='stopped'; NEW.position_seconds=0; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_wall_geometry BEFORE INSERT OR UPDATE ON public.video_walls FOR EACH ROW EXECUTE FUNCTION public.validate_wall_geometry();